// Stage 1: sample inputs once and derive valid reset
bStart := Start;
bStop := Stop;
bFault := Fault;
bReset := Reset;
validReset := bReset AND NOT bFault AND NOT bStart;

// Stage 2: priority transition using retained pre-state
IF validReset THEN
    mode := E_Mode.IDLE;
    attempt_count := 0;
    free_scans := 0;
ELSIF mode = E_Mode.LOCKED THEN
    // Latched lockout: remain LOCKED absent valid reset
    mode := E_Mode.LOCKED;
    free_scans := 0;
    // attempt_count preserved
ELSIF bStop THEN
    mode := E_Mode.IDLE;
    free_scans := 0;
    // attempt_count preserved
ELSE
    CASE mode OF
        E_Mode.IDLE:
            IF bStart AND NOT bFault THEN
                mode := E_Mode.RUNNING;
                free_scans := 0;
                // attempt_count preserved
            ELSE
                mode := E_Mode.IDLE;
                free_scans := 0;
                // attempt_count preserved
            END_IF;
        E_Mode.RUNNING:
            IF bFault THEN
                IF attempt_count >= 2 THEN
                    mode := E_Mode.LOCKED;
                    free_scans := 0;
                ELSE
                    mode := E_Mode.WAIT;
                    free_scans := 0;
                END_IF;
            ELSE
                mode := E_Mode.RUNNING;
                free_scans := 0;
            END_IF;
        E_Mode.WAIT:
            IF bFault THEN
                mode := E_Mode.WAIT;
                free_scans := 0;
            ELSIF (free_scans + 1) >= 2 THEN
                IF attempt_count < 2 THEN
                    attempt_count := attempt_count + 1;
                END_IF;
                free_scans := 0;
                mode := E_Mode.RUNNING;
            ELSE
                free_scans := free_scans + 1;
                mode := E_Mode.WAIT;
            END_IF;
        E_Mode.LOCKED:
            // Should not normally enter because handled by ELSIF, but keep safe latch
            mode := E_Mode.LOCKED;
            free_scans := 0;
        ELSE
            mode := E_Mode.IDLE;
            free_scans := 0;
            // attempt_count preserved
    END_CASE;
END_IF;

// Stage 3: no timer FB calls for SELF012 (scan-count dwell)

// Stage 4: unified output assignments from post-transition state
Run := (mode = E_Mode.RUNNING);
Locked := (mode = E_Mode.LOCKED);
